import{_ as i,a0 as r,w as l,s,ao as h,I as e,x as o,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"為什麼 Linux 的 htop 命令完勝 top 命令 | LCTT x X-CMD","titleTemplate":false,"description":"為什麼 Linux 的 htop 命令完勝 top 命令 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼 Linux 的 htop 命令完勝 top 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼 Linux 的 htop 命令完勝 top 命令 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/Why htop Command Compete Linux top Command","title":"為什麼 Linux 的 htop 命令完勝 top 命令","tag":"201406","desc":""},"relativePath":"201406/Why htop Command Compete Linux top Command.md","filePath":"[post].md"}'),d={name:"201406/Why htop Command Compete Linux top Command.md"};function m(u,t,x,g,f,c){const p=r("Link");return l(),s("div",null,[t[11]||(t[11]=h('<h1 id="為什麼-linux-的-htop-命令完勝-top-命令" tabindex="-1">為什麼 Linux 的 htop 命令完勝 top 命令 <a class="header-anchor" href="#為什麼-linux-的-htop-命令完勝-top-命令" aria-label="Permalink to “為什麼 Linux 的 htop 命令完勝 top 命令”">​</a></h1><p>在 Linux 系統中，top 命令用來顯示系統中正在運行的進程的實時狀態，它顯示了一些非常有用的信息，比如 CPU 利用情況、內存消耗情況，以及每個進程情況等。但是，你知道嗎？還有另外一個命令列工具 &#39;htop&#39;，它與傳統的 top 命令功能一樣，但它有更加強大的功能及能顯示更多的信息。這篇文章，我們會用實例來討論這個 &#39;htop&#39; 命令。</p><h3 id="linux-中的-htop-命令" tabindex="-1">Linux 中的 htop 命令 <a class="header-anchor" href="#linux-中的-htop-命令" aria-label="Permalink to “Linux 中的 htop 命令”">​</a></h3><p>下面是從 htop 的手冊頁摘抄下來的相關描述:</p><blockquote><p>它類似於 top 命令，但可以讓你在垂直和水平方向上滾動，所以你可以看到系統上運行的所有進程，以及他們完整的命令列。</p><p>可以不用輸入進程的 PID 就可以對此進程進行相關的操作 (killing, renicing)。</p></blockquote><h3 id="首先明白它的輸出" tabindex="-1">首先明白它的輸出 <a class="header-anchor" href="#首先明白它的輸出" aria-label="Permalink to “首先明白它的輸出”">​</a></h3><p><strong>htop 命令</strong>以直觀的格式來顯示信息。下面是 HTOP 的輸出快照:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/htop.png" alt="htop"></p><p>如果你觀察窗口的左上角部分，你會看到顯示的是 CPU 負載、內存消耗及交換空間的實時信息，右上角包含的是任務、線程、平均負載及系統運行時間的信息。</p><p>平均負載部分提供了三個數字，這僅僅表示的是過去的5分鐘、10分鐘和15分鐘系統的平均負載而已，在單核的系統中，平均負載為1表示的是百分之百的 CPU 利用率。最後，運行時間 （uptime）標示的數字是從系統啓動起到當前的運行總時間。</p><p>下面，我們將用例子來進一步討論這個命令。</p><h3 id="_1-用-f2-鍵編輯配置" tabindex="-1">1. 用 F2 鍵編輯配置 <a class="header-anchor" href="#_1-用-f2-鍵編輯配置" aria-label="Permalink to “1. 用 F2 鍵編輯配置”">​</a></h3><p>htop 命令提供了許多自定義選項，你所要做的就是從主窗口中按下 F2 鍵。</p><p>下面所示的是可用的自定義選項:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/htop-settings.png" alt="htop-settings"></p><p>只需使用箭頭鍵選擇和更改特定的設置。</p><h3 id="_2-通過-f9-鍵發送信號" tabindex="-1">2. 通過 F9 鍵發送信號 <a class="header-anchor" href="#_2-通過-f9-鍵發送信號" aria-label="Permalink to “2. 通過 F9 鍵發送信號”">​</a></h3><p>htop 命令可以讓你很容易地在 htop 窗口內給一個進程發送任意的信號。按下 F9 鍵即可。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/signals.png" alt="signals"></p><p>如你所見，窗口的左邊部分列出的是所有可用的信號，右邊部分列出的是進程。只要選中信號，並選擇一個進程，然後按下 enter 鍵，選中的信號就會發送到此進程。</p><h3 id="_3-顯示進程的樹狀視圖" tabindex="-1">3. 顯示進程的樹狀視圖 <a class="header-anchor" href="#_3-顯示進程的樹狀視圖" aria-label="Permalink to “3. 顯示進程的樹狀視圖”">​</a></h3><p>htop 命令也提供了進程的樹狀視圖查看功能。按下 F5 鍵切換。</p><p>下面是 htop 顯示樹形視圖信息的例子:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/treeView.png" alt="treeView"></p><p>要退出樹狀視圖模式，請再一次按下 F5 鍵。</p><h3 id="_4-通過-f3-鍵搜索進程" tabindex="-1">4. 通過 F3 鍵搜索進程 <a class="header-anchor" href="#_4-通過-f3-鍵搜索進程" aria-label="Permalink to “4. 通過 F3 鍵搜索進程”">​</a></h3><p>htop 命令提供了易用的方式來搜索進程。按下 F3 鍵，一個文本框就會出現在窗口底部。</p><p>下面是例子:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/search1.png" alt="search"></p><p>如您所見，一條名為‘搜索’的文本提示框出現在窗口底部，您可以在這兒輸入進程的名字然後回車搜索。如果找到，它會在列出的進程列表裏高亮選中此進程。</p><h3 id="_5-通過空格鍵來設置顏色標註進程條目" tabindex="-1">5. 通過空格鍵來設置顏色標註進程條目 <a class="header-anchor" href="#_5-通過空格鍵來設置顏色標註進程條目" aria-label="Permalink to “5. 通過空格鍵來設置顏色標註進程條目”">​</a></h3><p>在系統中運行着的實時進程視圖中，要追蹤某個進程是個大問題。因為整個列表在不停的刷新着，進程的排列順序也在變動着。為了這個問題， htop 提供了一個很簡單的解決方案：顏色標註。是的，你可以標註一個進程條目，它會以不同的顏色顯示，因此要追蹤它就變得容易了。</p><p>要標註某個進程條目，需要做的就是選中此條目，然後按下‘空格’鍵。例如，在下面的截圖示例中，我已經顏色標註了三個進程條目:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/color-tag.png" alt="color-tag"></p><p>所以通過此方法，你就能很輕鬆地追蹤想查看的進程。</p><h3 id="_6-命令列選項" tabindex="-1">6. 命令列選項 <a class="header-anchor" href="#_6-命令列選項" aria-label="Permalink to “6. 命令列選項”">​</a></h3><p>除了上面介紹的一些熱鍵，htop 還提供了很有用的命令列選項。下面是其中一部分:</p><ul><li><strong>-s 選項</strong> : 按指定的列排序。例如，<strong>htop -s PID</strong> 命令會按 PID 列的大小排序來顯示。</li><li><strong>-u 選項</strong> : 顯示指定的用户的進程信息列表。例如，<strong>htop -u himanshu</strong> 命令會只顯示出用户名為 himanshu 的相關進程。</li><li><strong>-d 選項</strong> : 設置刷新的延遲時間。例如，<strong>htop -d 100</strong> 命令會使輸出在1秒後才會刷新（參數 -d 的單位是10微秒）。</li></ul><hr>',39)),e("p",null,[t[1]||(t[1]=o("via: ",-1)),a(p,{href:"http://linoxide.com/linux-command/linux-htop-command/"},{default:n(()=>[...t[0]||(t[0]=[o("http://linoxide.com/linux-command/linux-htop-command/",-1)])]),_:1})]),e("p",null,[t[4]||(t[4]=o("譯者：",-1)),a(p,{href:"https://github.com/runningwater"},{default:n(()=>[...t[2]||(t[2]=[o("runningwater",-1)])]),_:1}),t[5]||(t[5]=o(" 校對：",-1)),a(p,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...t[3]||(t[3]=[o("Caroline",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=o("本文由 ",-1)),a(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原創翻譯，",-1)),a(p,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[o("Linux中國",-1)])]),_:1}),t[10]||(t[10]=o(" 榮譽推出",-1))])])}const _=i(d,[["render",m]]);export{T as __pageData,_ as default};
